import { DiscordSDK, Events } from '@discord/embedded-app-sdk';

const config=window.GL_CONFIG||{};
const query=new URLSearchParams(location.search);
const isDebug=query.get('debug')==='1';
const appId=String(config.discordClientId||'').trim();
const placeholder=!appId||appId.includes('PASTE_');
const $=id=>document.getElementById(id);
const esc=t=>{const d=document.createElement('div');d.textContent=String(t??'');return d.innerHTML};
const short=v=>String(v||'').length>42?`${String(v).slice(0,22)}…${String(v).slice(-12)}`:String(v||'');
const imageSrc=v=>{if(!v)return'';const s=String(v);if(s.startsWith('/'))return s;if(s.startsWith('runtime_thumbnail_assets/'))return '/'+s;return `/card-image?url=${encodeURIComponent(s)}`};
const runtimeImg=(rec,attrs='')=>{const normal=rec?.local_thumbnail_path||rec?.thumbnail_url||rec?.image_url||'',fallback=rec?.thumbnail_url||rec?.image_url||'',review=rec?.image_url||fallback;if(!normal)return'';return `<img ${attrs} loading="lazy" decoding="async" src="${esc(imageSrc(normal))}" data-fallback="${esc(imageSrc(fallback))}" data-review="${esc(imageSrc(review))}" onerror="if(!this.dataset.fallbackTried&&this.dataset.fallback){this.dataset.fallbackTried='1';this.src=this.dataset.fallback}">`};
const previewImg=(rec,attrs='')=>{const hd=rec?.image_url||rec?.thumbnail_url||'',thumb=rec?.thumbnail_url||hd;if(!hd)return'';return `<img ${attrs} decoding="async" src="${esc(imageSrc(hd))}" data-thumb="${esc(imageSrc(thumb))}" onerror="if(!this.dataset.thumbTried&&this.dataset.thumb){this.dataset.thumbTried='1';this.src=this.dataset.thumb}">`};

const lanes=['LEFT','CENTER','RIGHT'];
const stableClientId=query.get('client')||localStorage.getItem('glPvpClientId')||sessionStorage.getItem('glPvpClientId')||crypto.randomUUID();sessionStorage.setItem('glPvpClientId',stableClientId);localStorage.setItem('glPvpClientId',stableClientId);
const requestedRole=(query.get('spectate')==='1'||query.get('host')==='1'||['spectator','host'].includes(String(query.get('role')||'').toLowerCase()))?'spectator':(localStorage.getItem('glPvpPreferredRole')||'player');
const state={sdk:null,roomId:'',clientId:stableClientId,name:query.get('name')||localStorage.getItem('glPvpName')||'Player',role:requestedRole,preferredRole:requestedRole,spectatorHandView:'HIDDEN',socket:null,snapshot:null,ready:false,selection:null,reconnectTimer:null,reconnectAttempt:0,pingTimer:null,lastModalKind:null,seenCardNoticeIds:new Set(),seenReadonlyResponseKeys:new Set()};
const alliedTargetNames=new Set(['Blessing of Might','Blessing of Wisdom',"Heaven's Fury",'Arcane Scroll','Holy Medallion','Ring of Grace','Invisibility Cloak']);
const skillBuffNames=new Set(['Blessing of Might','Blessing of Wisdom',"Heaven's Fury"]);
const opponentTargetNames=new Set(['Scouting','Dazed']);

function local(text,kind=''){const el=document.createElement('div');el.textContent=`[${new Date().toLocaleTimeString()}] ${text}`;el.className=kind;const log=$('localLog');log?.append(el);if(log)log.scrollTop=log.scrollHeight}
function badge(cls,text){$('connectionBadge').className=`badge ${cls}`;$('connectionBadge').textContent=text}
function send(type,extra={}){if(state.socket?.readyState===1)state.socket.send(JSON.stringify({type,...extra}));else local('Socket is not connected.','error-text')}
function socketUrl(){const proto=location.protocol==='https:'?'wss:':'ws:';const params={room:state.roomId,client:state.clientId,name:state.name};if(state.preferredRole==='spectator'||query.get('spectate')==='1'||query.get('host')==='1')params.spectate='1';return `${proto}//${location.host}/ws?${new URLSearchParams(params)}`}
function openModal(html,closable=true,kind='generic'){$('modalBody').innerHTML=html;$('modalClose').style.display=closable?'block':'none';$('modal').classList.remove('hidden');state.lastModalKind=kind}
function closeModal(){$('modal').classList.add('hidden');$('modalBody').innerHTML='';state.lastModalKind=null}
$('modalClose').onclick=closeModal;

function stats(p){if(!p)return'<span class="small">Waiting.</span>';return `<span class=stat>Deck ${p.deckCount}</span><span class=stat>Hand ${p.handCount}</span><span class=stat>Mana ${p.mana}</span><span class=stat>Regen ${p.regen}</span><span class=stat>Racial ${p.racial}</span><span class=stat>Legacy ${p.sideAvailable}</span><span class=stat>Discard ${p.discardCount}</span>`}
function hpBar(h){if(h.legacy)return'';const pct=h.maxHp?Math.max(0,Math.min(100,Math.round(h.hp/h.maxHp*100))):0;return `<div class=hp><div class=fill style="width:${pct}%"></div></div>`}
function tags(h){const out=[];if(h.exhausted)out.push('Exhausted');if(h.legacy)out.push('Legacy');if(h.castingMode||h.actionZone)out.push('Casting Mode');if(h.statusText)out.push(h.statusText);return out.map(x=>`<span class=tag>${esc(x)}</span>`).join('')}
function attachmentSlots(h){if(h?.legacy)return'';const cards=Array.isArray(h?.attachments)?h.attachments:[];return `<div class=attachment-slots>${[0,1].map(i=>{const a=cards[i];return `<span class=attachment-slot title="${esc(a?.name||'Empty Attachment Slot')}">${a?esc(a.kind==='CASTING'?`CAST · ${a.name}`:`${a.buffType||'BUFF'} · ${a.name}${a.durationText?` · ${a.durationText}`:''}`):'EMPTY'}</span>`}).join('')}</div>`}
function heroCard(h,lane,own){if(!h)return `<div class="field-hero-zone ${lane==='CENTER'?'center':''}"><span class=field-position>${lane}</span><p class=small>Empty</p></div>`;const acts=[],hint=state.snapshot?.match?.hints||{},legacySlots=hint.legacySlots,racialSlots=hint.racialSlots,legacyAllowed=!Array.isArray(legacySlots)||legacySlots.includes(lane),racialAllowed=!Array.isArray(racialSlots)||racialSlots.includes(lane);if(own&&h.legacy&&legacyAllowed)acts.push(`<button data-use-legacy="${lane}">Use Legacy</button>`);if(own&&!h.legacy&&h.race!=='Dragonborn'&&racialAllowed)acts.push(`<button data-racial="${lane}">Racial</button>`);if(own&&!h.legacy&&['Paladin','Crusader'].includes(h.class))acts.push(`<button data-ability="${lane}">Ability · 1 Mana</button>`);const side=own?'you':'opponent',selectionClass=selectionHeroClass(side,lane,h);return `<article class="field-hero-zone ${lane==='CENTER'?'center':''} ${selectionClass}" data-hero-preview="${side}:${lane}">
<span class=field-position>${lane}</span>${runtimeImg(h,`class="hero-card-visual" alt="${esc(h.name)}"`)}
<div class=hero-meta><strong>${esc(h.name)}</strong><div class=small>${esc(h.race||'')} ${esc(h.class)} · ${esc(h.rank)}</div><div class=small>${h.legacy?'Legacy Card':`HP ${h.hp}/${h.maxHp} · EXP ${h.exp}`}</div>${hpBar(h)}<div class=tags>${tags(h)}</div>${attachmentSlots(h)}<div class=hero-actions>${acts.join('')}</div></div></article>`}
function field(id,p,own){$(id).innerHTML=lanes.map(l=>heroCard(p?.board?.[l],l,own)).join('')}
function cardTile(c,{playable=false,tribute=false,manaBlocked=false,response=false,choice=false}={}){const active=playable||tribute,blocked=manaBlocked&&!tribute;return `<article class="visual-card ${active?'play':''} ${blocked?'mana-blocked':''} ${response?'defcard':''}" data-preview-card="${c.index}">${runtimeImg(c,`data-card-image="${c.index}" alt="${esc(c.card_name)}"`)}<div class=visual-card-body><b>${esc(c.card_name)}</b><div class=small>${esc(c.card_type)} / ${esc(c.card_subtype)}${Number.isFinite(+c.mana_cost)?` · Mana ${c.mana_cost}`:''}</div><div class=hero-actions>${playable?`<button data-play="${c.index}">Play</button>`:''}${tribute?`<button data-tribute="${c.index}">Tribute</button>`:''}${response?`<button data-response="${c.index}">Choose</button>`:''}${choice?`<button data-choice="${c.index}">Choose</button>`:''}</div></div></article>`}
function renderHiddenHand(count){$('opponentHandCount').textContent=`— ${count}`;$('opponentHand').innerHTML=Array.from({length:count},()=>'<div class=card-back></div>').join('')}
function pile(id,value){const el=$(id);if(el)el.textContent=String(value??0)}
function resourceDiscardArt(id,count){const el=$(id),filled=Number(count||0)>0;if(el){el.classList.toggle('hidden',!filled);el.closest('.discard-art-zone')?.classList.toggle('empty-discard',!filled)}}
function renderPlaymatPiles(m){pile('yourManaPile',m.you?.mana);pile('yourManaRegen',m.you?.regen);pile('yourLegacyPile',m.you?.sideAvailable);pile('yourRacialPile',m.you?.racial);pile('yourDiscardPile',m.you?.discardCount);pile('yourDeckPile',m.you?.deckCount);pile('opponentManaPile',m.opponent?.mana);pile('opponentManaRegen',m.opponent?.regen);pile('opponentLegacyPile',m.opponent?.sideAvailable);pile('opponentRacialPile',m.opponent?.racial);pile('opponentDiscardPile',m.opponent?.discardCount);pile('opponentDeckPile',m.opponent?.deckCount);resourceDiscardArt('yourDiscardArt',m.you?.discardCount);resourceDiscardArt('opponentDiscardArt',m.opponent?.discardCount)}
function renderPlayers(s){state.role=s.role||'player';state.preferredRole=state.role;localStorage.setItem('glPvpPreferredRole',state.preferredRole);$('players').innerHTML=s.players.map(p=>`<div class="player-card ${p.ready?'is-ready':''} ${p.connected===false?'is-offline':''}"><div><b>Player ${p.seat}</b><br>${esc(p.name)}<br><span class=small>${p.deckLoaded?esc(p.deckName):'Deck not loaded'}</span></div><b>${p.connected===false?'OFFLINE':p.ready?'READY':p.deckLoaded?'LOADED':'WAITING'}</b></div>`).join('');const specs=s.spectators||[];$('spectatorSummary').innerHTML=specs.length?`<b>Spectators (${specs.length})</b><br><span class=small>${specs.map(x=>esc(x.name)).join(' · ')}</span>`:'<span class=small>No spectators connected.</span>';$('bothReady').className=`ready-banner ${s.bothReady?'ok':''}`;$('bothReady').textContent=state.role==='spectator'?'Spectator mode: read-only view. Waiting for the players to continue.':s.bothReady?'Both players are ready. Player 1 may start.':'Waiting for two loaded decks and Ready.';const me=s.players.find(p=>p.clientId===state.clientId);if(me){state.ready=me.ready}if($('lobbySetupButton'))$('lobbySetupButton').textContent=state.role==='spectator'?'Host / Spectator Info':'Open Deck + Setup';if($('roleSwitchButton')){$('roleSwitchButton').textContent=state.role==='spectator'?'Join as Player':'Host / Watch Only';$('roleSwitchButton').disabled=state.role==='spectator'&&(s.players?.length||0)>=2}}
function renderLogs(logs){const html=[...logs].map(x=>`<div class=server-entry>${String(x.seq).padStart(3,'0')}. ${esc(x.message)}</div>`).join('');const full=$('serverLog');if(full)full.innerHTML=html;const latest=[...logs].slice(-1)[0],latestEl=$('latestLogText');if(latestEl)latestEl.textContent=latest?`${String(latest.seq).padStart(3,'0')}. ${latest.message}`:'Waiting for match activity.';$('logCount').textContent=String(logs.length);if(full)full.scrollTop=full.scrollHeight}
function previewCard(c){if(!c)return;openModal(`<h2>${esc(c.card_name)}</h2><div class=preview>${previewImg(c)}<div><p><b>${esc(c.card_type)} / ${esc(c.card_subtype)}</b>${Number.isFinite(+c.mana_cost)?` · Mana ${c.mana_cost}`:''}</p><p>${esc(c.effect_text||'')}</p><p class=small>${esc(c.timing||'')}</p></div></div>`,true,'preview')}
function previewHero(h,lane,side){if(!h)return;openModal(`<h2>${esc(h.name)}</h2><div class=preview>${previewImg(h)}<div><p><b>${esc(side)} ${esc(lane)}</b></p><p>${esc(h.race||'')} ${esc(h.class)} · ${esc(h.rank)}</p><p>${h.legacy?'Legacy Card':`HP ${h.hp}/${h.maxHp} · EXP ${h.exp}`}</p>${h.statusText?`<p>Status: ${esc(h.statusText)}</p>`:''}${h.actionZone?`<p>Attachment Slot / Casting Mode: ${esc(h.actionZone)}</p>`:''}${h.legacyEffectText?`<p>${esc(h.legacyEffectText)}</p>`:''}${h.abilityText&&h.abilityText!=='None'?`<p><b>${esc(h.abilityName||'Hero Ability')}</b><br>${esc(h.abilityText)}</p>`:''}</div></div>`,true,'preview')}
function activeSlots(p){return lanes.filter(l=>p?.board?.[l]&&!p.board[l].legacy&&p.board[l].hp>0)}
function legacySlots(p){return lanes.filter(l=>p?.board?.[l]?.legacy)}
function hintedUsers(c){const h=state.snapshot?.match?.hints||{},mapped=h.playableUsersByCard?.[String(c?.index)];return Array.isArray(mapped)?mapped:activeSlots(state.snapshot?.match?.you)}
function alliedTargets(c,userSlot){const m=state.snapshot?.match;if(!m)return[];const all=activeSlots(m.you);if(c?.card_name==='Relentless Leveling')return[userSlot];if(c?.card_type==='Item'&&String(c?.target_type||'').toLowerCase().includes('allied hero'))return all;if(c?.card_type==='Skill'&&c?.card_subtype==='SUPPORT')return all;return all}
function laneAccess(mode,slot){if(mode==='QUICK')return lanes;if(slot==='LEFT')return['LEFT','CENTER'];if(slot==='RIGHT')return['CENTER','RIGHT'];return lanes}
function opponentTargets(c,userSlot){const m=state.snapshot?.match,h=m?.hints||{};if(h.dualCasting?.targetSlot)return[h.dualCasting.targetSlot];let active=activeSlots(m?.opponent);if(c?.card_name==='Scouting')active=active.filter(l=>(m.opponent?.board?.[l]?.expCards||[]).some(x=>!x.ultimate));if(!(c?.card_type==='Skill'&&c?.card_subtype==='ATK'))return active;const taunt=active.find(l=>m.opponent?.board?.[l]?.tmp?.taunt);const legal=laneAccess(m.mode,userSlot).filter(l=>active.includes(l)&&!m.opponent?.board?.[l]?.tmp?.untargetable&&!m.opponent?.board?.[l]?.tmp?.attackUntargetable);return taunt?legal.filter(l=>l===taunt):legal}
function selectionAllows(side,lane,h){const x=state.selection;if(!x||!h)return false;if(side==='you'){if(x.kind==='tribute'||x.kind==='ability')return !h.legacy&&h.hp>0&&(x.allowedTargets||[]).includes(lane);if(x.kind==='legacy-direct')return !!h.legacy;if(x.kind==='play'&&x.step==='user')return !h.legacy&&h.hp>0&&(x.allowedUsers||[]).includes(lane);if(x.kind==='play'&&(x.step==='allied'||x.step==='legacy'))return (x.allowedTargets||[]).includes(lane)}if(side==='opponent'&&x.kind==='play'&&x.step==='opponent')return !h.legacy&&h.hp>0&&(x.allowedTargets||[]).includes(lane);return false}
function selectionHeroClass(side,lane,h){const x=state.selection;if(!x||!h)return'';if(selectionAllows(side,lane,h))return'selectable';let relevant=false;if(side==='you'){if(x.kind==='tribute'||x.kind==='ability'||x.kind==='play'&&['user','allied'].includes(x.step))relevant=!h.legacy&&h.hp>0;else if(x.kind==='legacy-direct'||x.kind==='play'&&x.step==='legacy')relevant=!!h.legacy}else if(side==='opponent'&&x.kind==='play'&&x.step==='opponent')relevant=!!h;return relevant?'selection-blocked':''}
function phaseEligible(c,m=state.snapshot?.match){return !!m&&(m.hints?.playableCardIndexes||[]).includes(c.index)}
function affordable(c,m=state.snapshot?.match){return Number(c?.mana_cost||0)<=Number(m?.you?.mana||0)}
function currentCard(){const s=state.selection,m=state.snapshot?.match;if(!s||s.kind!=='play'||!m?.you?.hand)return null;return m.you.hand.find(x=>x.index===s.index)}
function targetMode(c){if(!c)return'self';if(['Final Grit','Phoenix Feather','Resurrection'].includes(c.card_name))return'legacy';if(c.card_name==='Relentless Leveling'||c.card_name==='Dual Casting')return'self';if(c.card_type==='Item'&&String(c.target_type||'').toLowerCase().includes('allied hero'))return'allied';if(c.card_type==='Skill'&&c.card_subtype==='ATK'){if(String(c.target_type||'').toLowerCase().includes('area'))return'self';return'opponent'}if(opponentTargetNames.has(c.card_name))return'opponent';if(alliedTargetNames.has(c.card_name)||String(c.heal??'').trim()!==''||(c.card_type==='Skill'&&c.card_subtype==='SUPPORT'&&String(c.target_type||'').toLowerCase().includes('one of your heroes')))return'allied';return'self'}
function selectionText(){const s=state.selection;if(!s)return'';if(s.kind==='tribute')return`Tribute: click the allied Hero that receives EXP from ${s.cardName}.`;if(s.kind==='ability')return`Hero Ability: click the allied Hero inside this Hero Area to heal.`;if(s.kind==='legacy-direct')return`${s.cardName}: click the matching Legacy replacement stack.`;if(s.kind==='play'&&s.step==='user')return`${s.cardName}: click one highlighted allied Hero to use this card.`;if(s.kind==='play'&&s.step==='allied')return`${s.cardName}: click the highlighted allied Hero target.`;if(s.kind==='play'&&s.step==='legacy')return`${s.cardName}: click the Legacy replacement stacked with the fallen allied Hero.`;if(s.kind==='play'&&s.step==='opponent')return(s.allowedTargets||[]).length?`${s.cardName}: click the highlighted opponent Hero target.`:`${s.cardName}: no legal opponent Hero target. Check Area, Taunt, Untargetable, or Holy Ring attack protection.`;return'Choose a highlighted Hero.'}
function renderSelection(){if(!state.selection){$('selectionBar').classList.add('hidden');$('selectionText').textContent='';return}$('selectionBar').classList.remove('hidden');$('selectionText').textContent=selectionText()}
function cancelSelection(){state.selection=null;closeModal();renderSelection();if(state.snapshot?.match)renderMatch(state.snapshot.match)}
$('cancelSelectionButton').onclick=cancelSelection;
function beginPlay(index){const c=state.snapshot?.match?.you?.hand?.find(x=>x.index===index);if(!c||!phaseEligible(c)||!affordable(c))return;if(['Final Grit','Phoenix Feather'].includes(c.card_name)){state.selection={kind:'legacy-direct',index,cardName:c.card_name};renderSelection();renderMatch(state.snapshot.match);return}state.selection={kind:'play',index,cardName:c.card_name,step:'user',allowedUsers:hintedUsers(c)};closeModal();renderMatch(state.snapshot.match)}
function beginTribute(index){const c=state.snapshot?.match?.you?.hand?.find(x=>x.index===index);if(!c)return;const allowed=state.snapshot?.match?.hints?.tributeTargetSlots||activeSlots(state.snapshot?.match?.you);state.selection={kind:'tribute',index,cardName:c.card_name,allowedTargets:allowed};closeModal();renderMatch(state.snapshot.match)}
function beginAbility(slot){const h=state.snapshot?.match?.hints||{},allowed=h.abilityTargetsBySlot?.[slot]||activeSlots(state.snapshot?.match?.you);state.selection={kind:'ability',userSlot:slot,allowedTargets:allowed};closeModal();renderMatch(state.snapshot.match)}
function opponentHeroClicked(lane){const s=state.selection;if(!s||s.kind!=='play'||s.step!=='opponent'||!(s.allowedTargets||[]).includes(lane))return;send('play-card',{index:s.index,userSlot:s.userSlot,targetSlot:lane});state.selection=null;renderSelection()}
function ownHeroClicked(lane){const s=state.selection;if(!s)return;if(s.kind==='tribute'){if(!(s.allowedTargets||[]).includes(lane))return;send('tribute',{index:s.index,slot:lane});state.selection=null;renderSelection();return}if(s.kind==='ability'){if(!(s.allowedTargets||[]).includes(lane))return;send('use-ability',{slot:s.userSlot,targetSlot:lane});state.selection=null;renderSelection();return}if(s.kind==='legacy-direct'){send('play-card',{index:s.index,targetSlot:lane});state.selection=null;renderSelection();return}if(s.kind!=='play')return;const c=currentCard();if(!c){cancelSelection();return}if(s.step==='user'){if(!(s.allowedUsers||[]).includes(lane))return;s.userSlot=lane;const mode=targetMode(c);if(mode==='opponent'){s.step='opponent';s.allowedTargets=opponentTargets(c,lane);if(!s.allowedTargets.length)local(`${c.card_name}: no legal opponent Hero target. Check Area, Taunt, Untargetable, or Holy Ring attack protection.`,'error-text');renderSelection();renderMatch(state.snapshot.match);return}if(mode==='allied'){s.step='allied';s.allowedTargets=alliedTargets(c,lane);renderSelection();renderMatch(state.snapshot.match);return}if(mode==='legacy'){s.step='legacy';s.allowedTargets=legacySlots(state.snapshot.match.you);renderSelection();renderMatch(state.snapshot.match);return}send('play-card',{index:s.index,userSlot:s.userSlot,targetSlot:s.userSlot});state.selection=null;renderSelection();return}if((s.step==='allied'||s.step==='legacy')&&(s.allowedTargets||[]).includes(lane)){send('play-card',{index:s.index,userSlot:s.userSlot,targetSlot:lane});state.selection=null;renderSelection()}}
function contextBlock(title,data){return `<section class=context-card><h3>${esc(title)}</h3>${runtimeImg(data,'class="context-hero-thumb"')}<p><b>${esc(data.name)}</b></p><p class=small>Player ${data.seat} · ${esc(data.slot)}</p><p>HP ${data.hp}/${data.maxHp}</p><p class=small>${esc(data.state||'Ready')}</p></section>`}
function responseModal(h){const incomingNotice=(state.snapshot?.cardNotices||[]).slice().reverse().find(n=>!state.seenCardNoticeIds.has(n.id)&&Number(n.sourceSeat)===Number(h.attacker?.seat)&&n.card_name===h.card_name);if(incomingNotice)state.seenCardNoticeIds.add(incomingNotice.id);const m=state.snapshot.match,opts=m.hints.responseCards||[],selected=h.selected,dragon=h.canDragonSkin?'<button id=dragonSkinResponse>Use Dragon Scale · Block 40</button>':'',tomes=(h.ancestralTomeSlots||[]).map(s=>`<button data-response-legacy="${s}">Use Ancestral Tome · ${s}</button>`).join('');const tiles=opts.map(c=>cardTile(c,{response:true})).join('')||'<p class=small>No legal response in hand.</p>';openModal(`<h2>Response Window</h2><div class=response-context>${contextBlock('Attacking Hero',h.attacker)}<section class="context-card incoming-card"><h3>Incoming Attack</h3>${runtimeImg({thumbnail_url:h.card_image_thumb,image_url:h.card_image})}<p><b>${esc(h.card_name)}</b></p><p>${h.damage} ${esc(h.attackType)} damage before DEF</p><p class=small>Attack Card mana cost: ${h.manaCost}</p><p class=small>Chain step ${h.chainStep}/3${h.aoe?` · Area DEF ${h.step}/${h.total}`:''}${h.redirected?' · Redirect follow-up':''}</p></section>${contextBlock('Receiving Hero',h.receiver)}</div>${selected?`<div class=selected-response><b>Selected response:</b> ${esc(selected.card_name)}${selected.redirectTarget?` → ${esc(selected.redirectTarget)}`:''}${selected.providerSlot?` · Provider ${esc(selected.providerSlot)}`:''}</div>`:''}<p class=response-note>Choose one legal response, review it, then resolve. Redirect recalculates the receiving Hero immediately and reopens the final-response window.</p><div class=response-grid>${tiles}</div><div class=modal-footer>${dragon}${tomes}<button id=passResponse>Pass / Take Hit</button><button id=resolveResponse class=primary>Resolve Selected Response / Apply Attack</button>${selected?'<button id=cancelResponse>Cancel Selected Response</button>':''}</div>`,false,'response');document.querySelectorAll('[data-response]').forEach(b=>b.onclick=()=>chooseResponse(+b.dataset.response,opts));document.querySelectorAll('[data-response-legacy]').forEach(b=>b.onclick=()=>send('use-legacy',{slot:b.dataset.responseLegacy}));if($('dragonSkinResponse'))$('dragonSkinResponse').onclick=()=>send('use-dragon-skin');$('passResponse').onclick=()=>send('pass-response');$('resolveResponse').onclick=()=>send('resolve-response');if($('cancelResponse'))$('cancelResponse').onclick=()=>send('cancel-response')}
