function clearSocketTimers(){clearTimeout(state.reconnectTimer);clearInterval(state.pingTimer);state.reconnectTimer=null;state.pingTimer=null}
function scheduleReconnect(){if(!state.roomId||state.reconnectTimer)return;const wait=Math.min(10000,1000*(2**Math.min(state.reconnectAttempt,3)));state.reconnectAttempt++;local(`Reconnect scheduled in ${wait/1000}s.`);state.reconnectTimer=setTimeout(()=>{state.reconnectTimer=null;connect()},wait)}
