function setupModal(){const s=state.snapshot,me=s?.players?.find(x=>x.clientId===state.clientId);if(s?.role==='spectator')return openModal(`<div class=spectator-panel><h2>Host / Spectator Mode</h2><div class=notice><b>Read-only room access</b><br>You can host the room without occupying Player 1 or Player 2. Public match flow remains visible.</div><div class=facts><div><span>Room</span><b>${esc(short(s?.roomId||state.roomId))}</b></div><div><span>Players</span><b>${s?.players?.length||0} / 2</b></div><div><span>Spectator View</span><b>${esc(s?.spectatorMode||'FAIR')}</b></div><div><span>Build</span><b>v${esc(config.transportVersion||'0.9.3-rc')}</b></div></div><label>Spectator Visibility<select id=spectatorModeSelect><option value=FAIR ${s?.spectatorMode==='FAIR'?'selected':''}>Fair Mode — hands hidden</option><option value=LEARNING ${s?.spectatorMode==='LEARNING'?'selected':''}>Learning Mode — spectator may study hands</option></select></label><div class=modal-footer><button id=applySpectatorMode>Apply Spectator Mode</button><button id=joinPlayerFromSpectator class=primary ${(s?.players?.length||0)>=2?'disabled':''}>Join as Player</button></div></div>`,true,'setup'),$('applySpectatorMode').onclick=()=>send('set-spectator-mode',{mode:$('spectatorModeSelect').value}),$('joinPlayerFromSpectator').onclick=()=>send('switch-role',{role:'player'});openModal(`<h2>Deck + Setup</h2><div class=setup-grid><section><label>Display Name<input id=nameInput maxlength=48 value="${esc(state.name)}"></label><label>Mode<select id=modeSelect><option value=MAIN>Main Mode</option><option value=QUICK>Quick Mode</option></select></label><label>Deck Source<select id=presetSelect><option value=starter_01_elemental_lord_conqueror_saint>Starter 01 — Elemental Lord / Conqueror / Saint</option><option value=starter_02_saint_crusader_conqueror>Starter 02 — Saint / Crusader / Conqueror</option><option value=starter_03_elemental_lord_renegade_grand_ranger>Starter 03 — Elemental Lord / Renegade / Grand Ranger</option><option value=starter_04_grand_ranger_crusader_saint>Starter 04 — Grand Ranger / Crusader / Saint</option><option value=starter_05_conqueror_crusader_renegade>Starter 05 — Conqueror / Crusader / Renegade</option></select></label><div class=modal-footer><button id=loadPresetButton>Load Starter Deck</button><label class=file-button>Import Custom Deck JSON<input id=deckFileInput type=file accept="application/json,.json"></label><a class=file-button href="/deck_builder.html" target=_blank>Open Deck Builder</a></div><div class="deck-status ${me?.deckLoaded?'ok':''}">${me?.deckLoaded?`Loaded: ${esc(me.deckName)} · Main ${me.mainDeckCount||50} · Legacy Deck ${me.legacyDeckCount||20}`:'No deck loaded.'}</div><div class=notice><b>Optional Starting Formation</b><br><span class=small>Change the three Rank I Hero positions briefly before Ready, or skip and keep the deck default.</span>${me?.deckLoaded?`<div class=setup-grid>${formationSelect('formationLeft','LEFT',me)}${formationSelect('formationCenter','CENTER',me)}${formationSelect('formationRight','RIGHT',me)}</div><div class=modal-footer><button id=confirmFormation>Confirm Formation</button><button id=skipFormation>Skip · Use Current Default</button></div>`:''}</div></section><section><div class=notice><b>Room:</b> ${esc(short(s?.roomId||state.roomId))}<br><b>Players:</b> ${s?.players?.length||0} / 2<br><b>Spectator View:</b> ${esc(s?.spectatorMode||'FAIR')}<br><b>Build:</b> v${esc(config.transportVersion||'0.9.3-rc')}</div><div class=modal-footer><button id=readyButton class=primary>${me?.ready?'Cancel Ready':'Ready'}</button><button id=startMatchButton class=primary ${s?.canStart?'':'disabled'}>Start Match</button><button id=inviteSetupButton>Invite Friend</button><button id=reconnectSetupButton>Reconnect</button></div></section></div>`,true,'setup');$('nameInput').onchange=()=>{state.name=$('nameInput').value.trim()||'Player';localStorage.setItem('glPvpName',state.name);send('rename',{name:state.name})};$('loadPresetButton').onclick=()=>{updateSetupDeckStatus('Loading preset…');loadPreset($('presetSelect').value).catch(e=>{updateSetupDeckStatus('Preset load failed.');local(String(e),'error-text')})};$('deckFileInput').onchange=async e=>{try{updateSetupDeckStatus('Importing deck JSON…');send('set-deck',{deck:JSON.parse(await e.target.files[0].text())})}catch(err){updateSetupDeckStatus('Deck import failed.');local(String(err),'error-text')}e.target.value=''};if($('confirmFormation'))$('confirmFormation').onclick=()=>send('set-formation',{formation:{LEFT:$('formationLeft').value,CENTER:$('formationCenter').value,RIGHT:$('formationRight').value}});if($('skipFormation'))$('skipFormation').onclick=()=>local('Starting formation kept from the loaded deck.','ok');$('readyButton').onclick=()=>send('ready',{ready:!state.ready});$('startMatchButton').onclick=()=>send('start-match',{mode:$('modeSelect').value});$('inviteSetupButton').onclick=()=>state.sdk?.commands.openInviteDialog().catch(e=>local(String(e),'error-text'));$('reconnectSetupButton').onclick=connect}

function roomModal(){const s=state.snapshot;openModal(`<h2>Activity Room</h2><div class=facts><div><span>Mode</span><b>${isDebug?'Browser Debug':'Discord Activity'}</b></div><div><span>Room</span><b>${esc(short(s?.roomId||state.roomId))}</b></div><div><span>Players</span><b>${s?.players?.length||0} / 2</b></div><div><span>Spectators</span><b>${s?.spectatorCount||0}</b></div><div><span>Build</span><b>v${esc(config.transportVersion||'0.9.3-rc')}</b></div><div><span>Alignment</span><b>S1B2 CSV v0.2.3 · Starter v2.0.1</b></div></div>`,true,'room')}
function castingModal(){const m=state.snapshot?.match;if(!m||m.status==='setup')return openModal('<h2>Casting Queue</h2><p class=small>No active match.</p>');const rows=m.spectator?[['Player 1',m.you],['Player 2',m.opponent]]:[['You',m.you],['Opponent',m.opponent]].flatMap(([name,p])=>(p.casting||[]).map(c=>`<div class=notice><b>${esc(name)} · ${esc(c.card_name)}</b><br><span class=small>Caster ${esc(c.slot)} · Target ${esc(c.targetSlot)} · Remaining ${c.remaining}</span></div>`));openModal(`<h2>Casting Queue</h2>${rows.join('')||'<p class=small>No unresolved Casting Skill Cards.</p>'}`,true,'casting')}
function discardModal(side){const p=state.snapshot?.match?.[side];if(!p)return;openModal(`<h2>${state.role==='spectator'?(side==='you'?'Player 1':'Player 2'):(side==='you'?'Your':'Opponent')} Discard Pile</h2><div class=choice-grid>${(p.discard||[]).map(c=>cardTile(c)).join('')||'<p class=small>Discard pile is empty.</p>'}</div>`,true,'discard');document.querySelectorAll('[data-card-image]').forEach(img=>img.onclick=()=>previewCard((p.discard||[]).find(c=>c.index===+img.dataset.cardImage)))}
function showActions(which){$('controlsSection').classList.toggle('hidden',which!=='controls');$('repositionSection').classList.toggle('hidden',which!=='reposition');$('showControlsButton').classList.toggle('active-tab',which==='controls');$('showRepositionButton').classList.toggle('active-tab',which==='reposition')}
$('openSetupButton').onclick=setupModal;$('lobbySetupButton').onclick=setupModal;$('roleSwitchButton').onclick=()=>send('switch-role',{role:state.role==='spectator'?'player':'spectator'});$('openRoomButton').onclick=roomModal;$('openCastingButton').onclick=castingModal;function openBottomDrawer(tab='battle'){const battle=tab!=='diagnostics';$('logDrawer').classList.add('open');$('battleLogTab').classList.toggle('hidden',!battle);$('diagnosticsTab').classList.toggle('hidden',battle);$('showBattleLogTab').classList.toggle('active-tab',battle);$('showDiagnosticsTab').classList.toggle('active-tab',!battle);$('drawerTitle').textContent=battle?'Battle Log':'Diagnostics'}$('openLogButton').onclick=()=>openBottomDrawer('battle');$('expandLogButton').onclick=()=>openBottomDrawer('battle');$('openDiagnosticsButton').onclick=()=>openBottomDrawer('diagnostics');$('showBattleLogTab').onclick=()=>openBottomDrawer('battle');$('showDiagnosticsTab').onclick=()=>openBottomDrawer('diagnostics');$('closeLogButton').onclick=()=>$('logDrawer').classList.remove('open');$('inviteButton').onclick=()=>state.sdk?.commands.openInviteDialog().catch(e=>local(String(e),'error-text'));$('reconnectButton').onclick=connect;$('showControlsButton').onclick=()=>showActions('controls');$('showRepositionButton').onclick=()=>showActions('reposition');$('nextPhaseButton').onclick=()=>send('next-phase');$('endTurnButton').onclick=()=>send('end-turn');$('surrenderButton').onclick=surrenderModal;document.querySelectorAll('[data-swap]').forEach(b=>b.onclick=()=>{const[a,c]=b.dataset.swap.split(',');send('reposition',{a,b:c})});$('openYourDiscardButton').onclick=()=>discardModal('you');$('fieldYourDiscardButton').onclick=()=>discardModal('you');$('openOpponentDiscardButton').onclick=()=>discardModal('opponent');$('fieldOpponentDiscardButton').onclick=()=>discardModal('opponent');
setupDiscord();


